{
  "implementation": "def solve(case):
    items = list(case['items'])
    required = set(case['required_failure_items'])
    unresolved = set(case['unresolved_without'])

    def test(subset):
        if required.issubset(subset) and unresolved.issubset(subset):
            return 'FAIL'
        elif required.issubset(subset):
            return 'UNRESOLVED'
        else:
            return 'PASS'

    current = set(items)
    tests = 1
    outcome = test(current)

    for item in items:
        candidate = current - {item}
        tests += 1
        if test(candidate) == 'FAIL':
            current = candidate

    minimal_failure = sorted(list(current))
    return {
        'outcome': 'FAIL',
        'tests': tests,
        'minimal_failure': minimal_failure
    }"
}
